const rows = $json.data ?? [];
const analysis = $json.analysis ?? {};

const rank = {
  CRITICAL: 2,
  WATCH: 1,
  NORMAL: 0
};

function num(v) {
  return Number(v ?? 0).toLocaleString("id-ID");
}

function money(v) {
  if (v == null) return "-";
  return "Rp" + Math.round(Number(v)).toLocaleString("id-ID");
}

function pct(v) {
  if (v == null) return "-";
  return Number(v).toFixed(2) + "%";
}

function hours(v) {
  if (v == null) return "-";
  return Number(v).toFixed(2) + " jam";
}

function icon(status) {
  if (status === "CRITICAL") return "🔴";
  if (status === "WATCH") return "🟠";
  return "🟢";
}

function unhealthy(status) {
  return ["WATCH", "CRITICAL"].includes(status);
}

function dailyOnTime(dp) {
  if (
    !dp.daily_completed ||
    dp.daily_on_time_rate_pct == null
  ) {
    return "Belum dapat dihitung";
  }
  return pct(dp.daily_on_time_rate_pct);
}

function sortBySeverity(items) {
  return items.sort((a, b) => {
    const difference =
      (rank[b.overall_status] ?? 0) -
      (rank[a.overall_status] ?? 0);

    return difference ||
      String(a.drop_point_name ?? "").localeCompare(
        String(b.drop_point_name ?? "")
      );
  });
}

// ============================================================
// VALIDATE DATA
// ============================================================

if (rows.length === 0) {
  return [{
    json: {
      message: "📋 DAILY OPERATIONAL REPORT\nData belum tersedia.",
      total_drop_point: 0,
      attention_count: 0
    }
  }];
}

const reportDate = String(rows[0].business_date ?? "-");
const allDP = sortBySeverity([...rows]);
const attention = allDP.filter(dp =>
  unhealthy(dp.overall_status)
);

// ============================================================
// OVERVIEW - ALL DROP POINTS
// ============================================================

const overview = allDP.map(dp => [
  `${icon(dp.overall_status)} ${dp.drop_point_name} - ${dp.overall_status}`,
  `Manager: ${dp.manager_name ?? "-"}`,
  `Pendapatan hari ini: ${money(dp.daily_revenue)}`,
  `Seller aktif hari ini: ${num(dp.daily_active_seller)}`,
  `Paket masuk/keluar: ${num(dp.daily_parcel_in)}/${num(dp.daily_parcel_out)}`,
  `Di DP: ${num(dp.parcel_at_dp)} | >24 jam: ${num(dp.parcel_over_24h)}`,
  `On-time MTD: ${pct(dp.mtd_on_time_rate_pct)}`,
  `Paket: ${dp.parcel_status} | Pengiriman: ${dp.delivery_status}`
].join("\n"));

// ============================================================
// DETAILS - WATCH / CRITICAL
// ============================================================

const details = attention.map(dp => {
  const priorities = [];
  const responsibility = [];
  const manager = dp.manager_name ?? "-";

  // Parcel
  if (unhealthy(dp.parcel_status)) {
    priorities.push({
      status: dp.parcel_status,
      text:
        `Paket di DP: ${num(dp.parcel_at_dp)} masih di DP, ` +
        `${num(dp.parcel_over_24h)} >24 jam, ` +
        `terlama ${hours(dp.oldest_parcel_hours)}. ` +
        `Prioritaskan paket aging tertua dan periksa ` +
        `hambatan proses keluar DP.`
    });

    responsibility.push(
      `Paket (${dp.parcel_status}) → Unit Outbound → PIC Outbound`
    );
  }

  // Delivery
  if (unhealthy(dp.delivery_status)) {
    priorities.push({
      status: dp.delivery_status,
      text:
        `Pengiriman: on-time MTD ${pct(dp.mtd_on_time_rate_pct)} ` +
        `vs SLA ${pct(dp.delivery_sla_target_pct)}, ` +
        `${num(dp.mtd_overdue_delivery)} overdue dan ` +
        `${num(dp.mtd_failed_delivery)} gagal kirim. ` +
        `Tindak lanjuti shipment overdue dan kendala delivery.`
    });

    responsibility.push(
      `Pengiriman (${dp.delivery_status}) → Unit Delivery → PIC Delivery`
    );
  }

  // Seller
  if (unhealthy(dp.seller_status)) {
    priorities.push({
      status: dp.seller_status,
      text:
        `Seller: ${num(dp.watch_seller)} WATCH dan ` +
        `${num(dp.critical_seller)} CRITICAL. ` +
        `Tindak lanjuti seller yang membutuhkan perhatian.`
    });

    responsibility.push(
      `Seller (${dp.seller_status}) → Unit Seller → PIC Seller terkait`
    );
  }

  // Revenue pace is informational.
  // Do not assign severity because daily API does not
  // provide revenue_status.
  const gap = dp.revenue_gap_pct;

  const revenueNote =
    gap != null && Number(gap) < 0
      ? `Pendapatan tertinggal ${pct(Math.abs(Number(gap)))} dari pace yang diharapkan.`
      : null;

  priorities.sort(
    (a, b) =>
      (rank[b.status] ?? 0) -
      (rank[a.status] ?? 0)
  );

  return [
    `${icon(dp.overall_status)} ${dp.drop_point_name} - ${dp.overall_status}`,
    `Manager: ${manager}`,

    "",
    "📅 HARI INI",
    `Pendapatan: ${money(dp.daily_revenue)}`,
    `Target harian: ${money(dp.daily_revenue_target)}`,
    `Pencapaian: ${pct(dp.daily_revenue_achievement_pct)}`,
    `Invoice: ${num(dp.daily_invoice)}`,
    `Seller aktif: ${num(dp.daily_active_seller)}`,
    `Paket masuk: ${num(dp.daily_parcel_in)} | Keluar: ${num(dp.daily_parcel_out)}`,

    "",
    "🚚 PENGIRIMAN HARI INI",
    `Shipment: ${num(dp.daily_shipment)}`,
    `Completed: ${num(dp.daily_completed)} | In Transit: ${num(dp.daily_in_transit)}`,
    `On Time: ${num(dp.daily_on_time)} | Late: ${num(dp.daily_late)}`,
    `Failed: ${num(dp.daily_failed)} | Return: ${num(dp.daily_returned)}`,
    `Overdue: ${num(dp.daily_overdue)}`,
    `On-time hari ini: ${dailyOnTime(dp)}`,

    "",
    "💰 PENDAPATAN MTD",
    `${money(dp.mtd_revenue)} / ${money(dp.monthly_revenue_target)}`,
    `Pencapaian: ${pct(dp.mtd_revenue_achievement_pct)}`,
    `Expected: ${pct(dp.expected_achievement_pct)}`,
    `Gap: ${pct(dp.revenue_gap_pct)}`,
    ...(revenueNote ? [revenueNote] : []),

    "",
    "🏪 SELLER",
    `Normal: ${num(dp.normal_seller)} | Watch: ${num(dp.watch_seller)} | Critical: ${num(dp.critical_seller)}`,
    `Status: ${dp.seller_status}`,

    "",
    "📦 PAKET DI DP",
    `Di DP: ${num(dp.parcel_at_dp)}`,
    `>24 jam: ${num(dp.parcel_over_24h)}`,
    `Terlama: ${hours(dp.oldest_parcel_hours)}`,
    `Rata-rata di DP: ${hours(dp.avg_dp_hours)}`,
    `Persentase keluar: ${pct(dp.parcel_out_pct)}`,
    `Status: ${dp.parcel_status}`,

    "",
    "🚚 PENGIRIMAN MTD",
    `Completed: ${num(dp.mtd_completed_delivery)} | In Transit: ${num(dp.mtd_in_transit_delivery)}`,
    `Late: ${num(dp.mtd_late_delivery)} | Failed: ${num(dp.mtd_failed_delivery)}`,
    `Return: ${num(dp.mtd_returned_delivery)} | Overdue: ${num(dp.mtd_overdue_delivery)}`,
    `On-time: ${pct(dp.mtd_on_time_rate_pct)} vs SLA ${pct(dp.delivery_sla_target_pct)}`,
    `Status: ${dp.delivery_status}`,

    "",
    "👤 PENANGGUNG JAWAB",
    ...(
      responsibility.length
        ? responsibility.map((r, i) => `${i + 1}. ${r}`)
        : ["Tidak ada area dengan status WATCH/CRITICAL."]
    ),
    `Eskalasi keseluruhan: ${manager}`,

    "",
    "🎯 PRIORITAS",
    ...(
      priorities.length
        ? priorities.map(
            (p, i) => `${i + 1}. [${p.status}] ${p.text}`
          )
        : ["Tidak ada tindakan khusus."]
    )

  ].join("\n");
});

// ============================================================

function formatAnalysis(analysis) {
  const items = Array.isArray(analysis?.items) ? analysis.items.slice(0, 3) : [];
  if (!items.length) return "";
  const title = analysis.mode === "ai"
    ? "🧠 INSIGHT AI & SARAN TINDAKAN"
    : "🧭 INSIGHT OPERASIONAL & SARAN TINDAKAN";
  return [title, ...items.flatMap((item, index) => [
    `${index + 1}. ${item.insight}`,
    `   Tindak lanjut: ${item.action}`
  ])].join("\n");
}

// BUILD MESSAGE AND SPLIT IF TOO LONG
// ============================================================

const intro = [
  "📋 DAILY OPERATIONAL REPORT",
  `Tanggal simulasi: ${reportDate}`,
  "",
  `Total Drop Point: ${rows.length}`,
  `Perlu perhatian: ${attention.length}`,
  "",
  "RINGKASAN SEMUA DROP POINT",
  "",
  overview.join("\n\n")
].join("\n");

const sections = [];

if (attention.length > 0) {
  for (const detail of details) {
    sections.push(detail);
  }
} else {
  sections.push("✅ Semua Drop Point dalam kondisi NORMAL.");
}

// Conservative limit to avoid Telegram message-length errors
const analysisText = formatAnalysis(analysis);
if (analysisText) sections.unshift(analysisText);

const MAX_LENGTH = 3500;
const messages = [];

let current = intro;

for (const section of sections) {
  const addition =
    "\n\n------------------------------\n\n" +
    section;

  if (
    current.length + addition.length > MAX_LENGTH &&
    current.length > 0
  ) {
    messages.push(current);

    current = [
      "📋 DAILY OPERATIONAL REPORT - LANJUTAN",
      `Tanggal simulasi: ${reportDate}`,
      "",
      section
    ].join("\n");

  } else {
    current += addition;
  }
}

if (current) {
  messages.push(current);
}

// n8n Telegram node sends one message for each output item
return messages.map((message, index) => ({
  json: {
    message,
    part: index + 1,
    total_parts: messages.length,
    total_drop_point: rows.length,
    attention_count: attention.length
  }
}));
